Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ ?M ?A _ => assert_fails (is_evar M); match goal with H : rw_cells _ M A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
          | |- u8arr _ ?M ?A _ => assert_fails (is_evar M); match goal with H : u8arr _ M A _ |- _ => exact H end
          end
        | eassumption ].
(* [comment removed for export] *)
Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;     (* [comment removed for export] *)
      change (Z.of_nat (cells_size cs)) with v
  end.
(* [comment removed for export] *)
Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Lemma outside_of_not_rin : forall (X : list (Z * Z)) a, ~ rin_ivs X a -> outside X a.
Proof.
  induction X as [|[l h] X IH]; intros a NR; cbn in *; [exact I|].
  split; [intros K; apply NR; left; exact K| apply IH; intros K; apply NR; right; exact K].
Qed.

(* [comment removed for export] *)
Definition AFieldsOwn (LB : list block) (em : gmap Z elt) : Prop :=
  forall e d, em !! e = Some d ->
    exists p, In (p, e, esize d) LB /\ esize d = elem_block_size (el_name d) (el_value d).

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma AFieldsC_ext : forall m m' Fa S L ns ls em,
  AFieldsC m Fa S L ns ls em ->
  (forall A cs, rw_cells bsegs m A cs ->
     (Fa <= A /\ A + Z.of_nat (cells_size cs) <= Fa + 48)
     \/ (exists e d, em !! e = Some d /\ e <= A /\ A + Z.of_nat (cells_size cs) <= e + esize d) ->
     rw_cells bsegs m' A cs) ->
  (forall e d, em !! e = Some d -> addressable m e (esize d) -> addressable m' e (esize d)) ->
  (accessible m Fa 48 -> accessible m' Fa 48) ->
  AFieldsC m' Fa S L ns ls em.
Proof.
  intros m m' Fa S L ns ls em FC TC TA TH.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE' & EOK & ESH & HA & HS).
  split.
  { intros a nd La. destruct (NC a nd La) as [WF [pad C]]. split; [exact WF|]. exists pad.
    apply TC; [exact C|]. rewrite NodeCells_size.
    destruct (AFieldsC_node_in _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _)]; [left; lia| right].
    exists (a - 16), d. pose proof (esize_ge d). split; [exact Ld| lia]. }
  split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|].
    apply TC; [exact C|]. rewrite LNodeCells_size.
    destruct (AFieldsC_lnode_in _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _)]; [left; lia| right].
    exists a, d. pose proof (esize_ge d). split; [exact Ld| lia]. }
  split.
  { intros e d Ld. apply TC; [exact (EC e d Ld)|]. right. exists e, d. split; [exact Ld|]. rewrite ValCells_size. lia. }
  split; [exact OK|]. split; [exact SO|]. split; [exact DL|]. split; [exact SL|]. split; [exact LE'|].
  split; [exact EOK|].
  split. { intros e d Ld. apply TA; [exact Ld| exact (ESH e d Ld)]. }
  split; [| exact HS]. destruct HA as (AP & AL & AC). split; [exact AP|]. split; [exact AL| exact (TH AC)].
Qed.

