Definition ins_frame (m : mem) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 : word) (j8 : list byte) : Prop :=
  rw_cells bsegs m (bv_unsigned sp + -80) [CB 8 j8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition ins_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa f np vp ecA : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j8 j24 s3x p5 msk vp',
    ms' = MS (mkR (Z_to_bv 64 P_A_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) s3x (Z_to_bv 64 (zlength (trim value))) (Z_to_bv 64 msk)
                  (Z_to_bv 64 2147450880) (Z_to_bv 64 p5) s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (ecA, ecA + 24)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -176)
    /\ ins_frame m' sp ra s0 s1 s2 s3 s4 s5 s6 s7 j8
    /\ tc_frame m' (Z_to_bv 64 (bv_unsigned sp + -80)) (Z_to_bv 64 P_A_INS_RET1) (Z_to_bv 64 ecA) (Z_to_bv 64 Fa)
         (Z_to_bv 64 (zlength value)) (Z_to_bv 64 vp) (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np)
         (Z_to_bv 64 f) (Z_to_bv 64 2147450880) j24
    /\ rw_cells bsegs m' ecA (ErrCodeCells EC_clear)
