(* [comment removed for export] *)
Definition ins_seg3_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa A : Z) (d : elt) (L : list Z) (em : gmap Z elt) (ecA lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' S' L' ns' ls',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (insW lo (bv_unsigned sp) Fa (A :: L)) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ AFieldsC m' Fa S' L' ns' ls' (<[A := d]> em) /\ (A + 16) ∈ S' /\ A ∈ L'
    /\ rw_cells bsegs m' ecA (ErrCodeCells EC_clear)
    /\ ACONST m' /\ stack0 m' lo shi.

Definition INS_SEG3_STACK : Z := INSEL_STACK.

Definition ins_seg3_stmt : Prop := forall (Fa A ecA : Z) (d : elt) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (lo shi : Z) (j8 junk : list byte)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 s2x s3x s4x s5x s6x : word)
    (F : bvmap 5 word) fc (m : mem),
  ins_frame m sp ra s0 s1 s2 s3 s4 s5 s6 s7 j8 ->
  rw_cells bsegs m ecA (ErrCodeCells EC_clear) ->
  AFieldsC m Fa S L ns ls em ->
  rw_cells bsegs m A [CB 48 junk] -> rw_cells bsegs m (A + 48) (ValCells d) -> new_elt_ok Fa em A d ->
  (ecA + 24 <= Fa \/ Fa + 48 <= ecA) -> (ecA + 24 <= A \/ A + esize d <= ecA) ->
  (forall e' d', em !! e' = Some d' -> ecA + 24 <= e' \/ e' + esize d' <= ecA) ->
  stk bsegs m lo (bv_unsigned sp + -80) -> lo + INS_SEG3_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  aapp ecA 24 -> ecA mod 8 = 0 -> accessible m ecA 24 ->
  addressable m A (esize d) -> shvis m (A + 16) (A + 48) ->
  evt bsegs (ins_seg3_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa A d L em ecA lo shi m)
