  Lemma ofi_spec : ofi_stmt.
  Proof.
    unfold ofi_stmt, ins_stmt_at.
    intros until errv. intros VIS -> E1 E2 E3 E4 E5 E6. intros FC OWN NB VB VHI NL VL FB ECC ECF ECN ECV HP KREL BUD BUDC AUX SPB ST CEIL LO ERR MI TP SP16
                              P0 AOH AOE EAL ACE ECE AON ACN AOV ACV RF LFN AC SK SHI COST.
    pose proof (aobj_aapp H HH _ _ _ _ _ _ _ HP RF AOH) as BPH2.
    pose proof (aapp_bounds _ _ BPH2 ltac:(lia)) as (HB1 & HB2 & HB3 & HB4 & HB5). unfold AAPP_HI in HB3.
    eapply (ahh_evt_then H HH); [exact KREL| exact VIS| apply ofi_prefix; lia|].
    intros msF1 mo1 KREL1 MP1 VIS1.
    pose proof ins_spec as IS. unfold ins_stmt, ins_stmt_at in IS.
    eapply (ah_mono H HH).
    { eapply IS with (msF := msF1) (m := m) (mo := mo1) (s := s) (LB := LB) (LF := LF) (P := P + 80) (f := f) (np := np) (vp := vp) (ecA := ecA)
                     (name := name) (value := value) (E0 := E0) (S := S) (L := L) (ns := ns) (ls := ls) (em := em) (lo := lo) (B := B) (shi := shi) (errv := errv);
        rewrite ?Z.add_0_r; try fast_eassumption; try reflexivity; try exact VIS1; try (clear - P0; lia). }
    intros c PO. unfold ins_post in *. rewrite ?Z.add_0_r in PO.
    destruct PO as (z0 & z1 & z2 & e0 & e1 & e2 & e3 & e4 & e5 & e6 & e7 & z3 & z4 & z5 & z6 & m4 & errv4 & s4' & p & A & pad & tl & S' & L' & ns' & ls' & XS
                    & V & K & MP & REST).
    do 15 eexists. exists m4, errv4, s4', p, A, pad, tl, S', L', ns', ls', XS.
    split; [exact V|]. split; [exact K|]. split; [eapply (ah_mpres_trans H HH); [exact MP1| exact MP]| exact REST].
  Qed.
